package timex_test

import (
	"testing"
	"time"

	"github.com/egdaemon/eg/internal/timex"
	"github.com/stretchr/testify/require"
)

// DO NOT EDIT: This file was auto generated by egautotest.

func TestAdjustableClockSet(t *testing.T) {
	t.Run("sets the clock to the given time", func(t *testing.T) {
		clk := timex.NewAdjustableClock(time.Date(2024, 1, 1, 0, 0, 0, 0, time.UTC))
		clk.Set(time.Date(2025, 6, 15, 12, 30, 45, 999999999, time.UTC))
		require.Equal(t, time.Date(2025, 6, 15, 12, 30, 45, 999999999, time.UTC), clk.Now())
	})

	t.Run("overwrites a previously set time", func(t *testing.T) {
		clk := timex.NewAdjustableClock(time.Date(2024, 1, 1, 0, 0, 0, 0, time.UTC))
		clk.Set(time.Date(2024, 2, 1, 0, 0, 0, 0, time.UTC))
		clk.Set(time.Date(2024, 3, 1, 0, 0, 0, 0, time.UTC))
		require.Equal(t, time.Date(2024, 3, 1, 0, 0, 0, 0, time.UTC), clk.Now())
	})

	t.Run("sets to zero time", func(t *testing.T) {
		clk := timex.NewAdjustableClock(time.Date(2024, 1, 1, 0, 0, 0, 0, time.UTC))
		clk.Set(time.Time{})
		require.Equal(t, time.Time{}, clk.Now())
	})

	t.Run("sets to a time in the past", func(t *testing.T) {
		clk := timex.NewAdjustableClock(time.Date(2025, 1, 1, 0, 0, 0, 0, time.UTC))
		clk.Set(time.Date(2000, 12, 31, 23, 59, 59, 0, time.UTC))
		require.Equal(t, time.Date(2000, 12, 31, 23, 59, 59, 0, time.UTC), clk.Now())
	})

	t.Run("sets to a time in the future", func(t *testing.T) {
		clk := timex.NewAdjustableClock(time.Date(2000, 1, 1, 0, 0, 0, 0, time.UTC))
		clk.Set(time.Date(2100, 1, 1, 0, 0, 0, 0, time.UTC))
		require.Equal(t, time.Date(2100, 1, 1, 0, 0, 0, 0, time.UTC), clk.Now())
	})

	t.Run("sets to the same time as current", func(t *testing.T) {
		ts := time.Date(2024, 7, 4, 10, 20, 30, 500000000, time.UTC)
		clk := timex.NewAdjustableClock(ts)
		clk.Set(ts)
		require.Equal(t, ts, clk.Now())
	})
}
